const raw = $json || {};
const query = raw.query || {};
const body = raw.body || {};
const metadata = raw.metadata || {};

const DEFAULT_CLIENT_ID = 'e3cf4d5e-a16d-4b64-8751-c7444c60ad26';
const DEFAULT_COMPANY_NAME = 'Empresa de Prueba';

const rawSessionId = raw.sessionId || body.sessionId || query.sessionId || $execution?.id || 'default';
const userMsg = (
  raw.chatInput ||
  raw.message ||
  raw.text ||
  body.chatInput ||
  body.message ||
  ''
).trim();

const clientId = String(
  raw.client_id || raw.clientId ||
  body.client_id || body.clientId ||
  query.client_id || query.clientId ||
  metadata.client_id ||
  DEFAULT_CLIENT_ID
).trim();

const companyName = String(
  raw.company_name || raw.companyName ||
  body.company_name || body.companyName ||
  query.company_name || query.companyName ||
  metadata.company_name ||
  DEFAULT_COMPANY_NAME
).trim();

// URL del endpoint de configuración del bot en WordPress
const botConfigUrl = String(
  raw.bot_config_url || body.bot_config_url || metadata.bot_config_url || ''
).trim();

if (!clientId) throw new Error('client_id es obligatorio para aislar el chatbot por cliente');

const sessionId = `${clientId}:${rawSessionId}`;

return [{ json: { ...raw, sessionId, rawSessionId, userMsg, clientId, client_id: clientId, companyName, company_name: companyName, botConfigUrl } }];

const prep = $('Extraer Datos Entrada').first().json;
const configRaw = $json || {};

// Si la llamada falló o no hay system_prompt, usamos defaults
const systemPrompt = configRaw.system_prompt || `Eres el asistente virtual de ${prep.companyName || 'la empresa'}. Habla de forma natural y directa. Responde solo con información de la base de conocimiento de la empresa. Nunca inventes servicios, precios ni compromisos.`;
const welcomeMsg   = configRaw.welcome_message || `¡Hola! Soy el asistente de ${prep.companyName}. ¿Cómo te llamas?`;
const leadTrigger  = configRaw.lead_trigger || 'LEAD_CAPTURED';
const leadEnabled  = configRaw.lead_capture_enabled !== false;

const filters = configRaw.filters || {
  spam: true,
  insults: true,
  long_msg: true,
  max_msg_length: 800,
  spam_reply: 'Lo siento, no puedo procesar mensajes con ese tipo de contenido.',
  insult_reply: 'Por favor, mantén un tono respetuoso para que pueda ayudarte.',
  long_msg_reply: 'El mensaje es demasiado largo. ¿Puedes resumir tu consulta en pocas frases?'
};

const aiConfig = configRaw.ai || {
  model: 'meta-llama/llama-3.3-70b-instruct',
  temperature: 0.7,
  max_tokens: 1000
};

return [{
  json: {
    ...prep,
    systemPrompt,
    welcomeMsg,
    leadTrigger,
    leadEnabled,
    filters,
    aiConfig,
    botConfigLoaded: !!configRaw.system_prompt
  }
}];

const config = $json;
const userMsg   = config.userMsg || '';
const msgLower  = userMsg.toLowerCase();
const filters   = config.filters || {};

const BANNED_DOMAINS = [
  'bit.ly', 'tinyurl.com', 'cutt.ly', 'shorturl.at',
  'ow.ly', 't.co', 'rebrand.ly', 'bl.ink',
  'onlyfans.com', 'xvideos.com', 'pornhub.com',
  'casino', 'bet365', 'betfair'
];

const BLOCKED_PATTERNS = [
  /\b(puta|puto|coño|hostia|gilipollas|imbécil|idiota|estupido|subnormal|retrasado|zorra|cabrón|hdp|hijo de puta|mierda de empresa)\b/i,
  /\b(te voy a|os voy a|voy a).{0,30}(matar|pegar|hundir|denunciar|destruir|arruinar|reventar|joder)\b/i,
  /\b(buy now|click here|free money|earn (fast|easy|quick)|guaranteed income|work from home|make money fast|crypto investment)\b/i,
  /\b(ignore (previous|all|your) (instructions?|rules?|prompt)|forget (your|the) (instructions?|rules?|context)|act as (dan|jailbreak|unrestricted|evil)|pretend (you are|to be) (without|no) (restrictions?|limits?))\b/i,
  /https?:\/\/[^\s]{60,}/i,
  /\b(\d{1,3}\.){3}\d{1,3}\b/
];

const maxLen = parseInt(filters.max_msg_length) || 800;
const urlsEnMensaje = msgLower.match(/https?:\/\/[^\s]+|www\.[^\s]+/gi) || [];
const dominiosBloqueados = filters.spam !== false && urlsEnMensaje.some(url => BANNED_DOMAINS.some(d => url.includes(d)));
const tieneInsultos = filters.insults !== false && BLOCKED_PATTERNS.some(p => p.test(userMsg));
const esDemasiado   = filters.long_msg !== false && userMsg.length > maxLen;

let bloqueado = false;
let motivoBloqueo = '';
if (dominiosBloqueados) { bloqueado = true; motivoBloqueo = 'dominio_baneado'; }
else if (tieneInsultos) { bloqueado = true; motivoBloqueo = 'contenido_bloqueado'; }
else if (esDemasiado)   { bloqueado = true; motivoBloqueo = 'mensaje_excesivo'; }

const respuestasBloqueo = {
  dominio_baneado:     filters.spam_reply    || 'Lo siento, no puedo procesar mensajes con ese tipo de enlaces.',
  contenido_bloqueado: filters.insult_reply  || 'Por favor, mantén un tono respetuoso para que pueda ayudarte.',
  mensaje_excesivo:    filters.long_msg_reply|| 'El mensaje es demasiado largo. ¿Puedes resumir tu consulta en pocas frases?'
};

return [{ json: { ...config, bloqueado, motivoBloqueo, respuestaBloqueo: bloqueado ? (respuestasBloqueo[motivoBloqueo] || 'Mensaje no permitido.') : null } }];

const prep = $('Preparar Config').first().json;
const sessionId    = prep.sessionId;
const clientId     = prep.clientId || prep.client_id || '';
const companyName  = prep.companyName || prep.company_name || 'la empresa';
const leadTrigger  = prep.leadTrigger || 'LEAD_CAPTURED';
const agentRaw     = ($json.output || '').trim();
const agentLimpio  = agentRaw.replace(new RegExp(leadTrigger + '[\\s\\S]*', 'gi'), '').trim();

return [{ json: { ...$json, sessionId, clientId, client_id: clientId, companyName, company_name: companyName, leadTrigger, agentLimpio } }];

const rawOutput   = ($('Preparar Respuesta Agente').first().json.output || '').trim();
const prep        = $('Preparar Config').first().json;
const leadTrigger = prep.leadTrigger || 'LEAD_CAPTURED';
const clientMeta  = {
  clientId:     prep.clientId,
  client_id:    prep.client_id,
  companyName:  prep.companyName,
  company_name: prep.company_name
};

if (!rawOutput) {
  return [{ json: { output: '¿En qué más puedo ayudarte?', hasLead: false, ...clientMeta } }];
}

const triggerRegex = new RegExp(leadTrigger.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*[:({]');
const corteIndex   = rawOutput.search(triggerRegex);
let cleanOutput    = rawOutput;
let leadPart       = null;

if (corteIndex !== -1) {
  cleanOutput = rawOutput.substring(0, corteIndex).trim();
  leadPart    = rawOutput.substring(corteIndex).trim();
}

cleanOutput = cleanOutput
  .replace(new RegExp(leadTrigger + '[\\s\\S]*', 'gi'), '')
  .replace(/\{[\s\S]*"nombre"[\s\S]*\}/gi, '')
  .trim();

if (/^[\[{]/.test(cleanOutput)) cleanOutput = '';

if (leadPart) {
  try {
    const jsonMatch = leadPart.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const leadData = JSON.parse(jsonMatch[0]);
      const nombre   = (leadData.nombre   || '').replace(/[\[\]]/g, '').trim();
      const email    = (leadData.email    || '').replace(/[\[\]]/g, '').trim();
      const telefono = (leadData.telefono || '').replace(/[\[\]]/g, '').trim();
      const placeholders = ['[nombre]','[email]','[telefono]','[nombre real]','[email real]','[telefono real]'];
      const tieneplaceholders = placeholders.some(p => nombre.toLowerCase() === p || email.toLowerCase() === p || telefono.toLowerCase() === p);
      const esValido = !tieneplaceholders && nombre.length > 1 && (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || telefono.replace(/\D/g, '').length >= 6);
      if (esValido) {
        if (!cleanOutput) {
          cleanOutput = `Perfecto, ${nombre}. Ya lo tenemos apuntado, te contactamos en breve. Cualquier duda, aquí estoy.`;
        }
        return [{
          json: {
            output: cleanOutput,
            hasLead: true,
            ...clientMeta,
            lead: {
              nombre,
              email,
              telefono,
              producto_interes: (leadData.producto_interes || 'General').replace(/[\[\]]/g, '').trim(),
              contexto:         (leadData.contexto || '').trim(),
              origen:           (leadData.origen || 'chatbot').trim(),
              timestamp:        leadData.timestamp || new Date().toISOString()
            }
          }
        }];
      }
    }
  } catch (e) {}
}

return [{ json: { output: cleanOutput || 'Disculpa, ¿en qué más puedo ayudarte?', hasLead: false, ...clientMeta } }];

const detected = $('Detectar Lead').first().json;
const prep     = $('Preparar Config').first().json;
const lead     = detected.lead || {};

return [{
  json: {
    ...detected,
    sessionId:    prep.sessionId,
    clientId:     prep.clientId || prep.client_id,
    client_id:    prep.clientId || prep.client_id,
    companyName:  prep.companyName || prep.company_name,
    company_name: prep.companyName || prep.company_name,
    lead
  }
}];

const lead     = $('Preparar Lead Local').first().json.lead;
const respuesta = $json;

return [{
  json: {
    client_id:        $('Preparar Lead Local').first().json.clientId || $('Preparar Lead Local').first().json.client_id,
    nombre:           lead.nombre,
    email:            lead.email,
    telefono:         lead.telefono,
    producto_interes: lead.producto_interes || 'General',
    contexto:         lead.contexto || '',
    origen:           lead.origen || 'chatbot',
    estado:           'OK',
    error_detalle:    null,
    respuesta_api:    JSON.stringify(respuesta)
  }
}];

const prep     = $('Preparar Config').first().json;
const sessionId   = prep.sessionId;
const clientId    = prep.clientId || prep.client_id || '';
const companyName = prep.companyName || prep.company_name || 'la empresa';
const logData     = $('Preparar Log OK').first().json || {};

return [{ json: {
  sessionId,
  clientId, client_id: clientId,
  companyName, company_name: companyName,
  leadNombre: logData.nombre           || 'Desconocido',
  leadEmail:  logData.email            || '',
  leadTel:    logData.telefono         || '',
  leadProd:   logData.producto_interes || 'General',
  leadCtx:    logData.contexto         || ''
} }];

const prepData    = $('Preparar Datos Transcript').first().json;
const clientId    = prepData.clientId || prepData.client_id || '';
const companyName = prepData.companyName || prepData.company_name || 'la empresa';
const leadNombre  = prepData.leadNombre;
const leadEmail   = prepData.leadEmail;
const leadTel     = prepData.leadTel;
const leadProd    = prepData.leadProd;
const leadCtx     = prepData.leadCtx;

const items   = $input.all();
const historia = items.map(item => item.json).filter(m => m.role && m.content);

const now           = new Date();
const timestamp     = now.toISOString();
const fechaLegible  = now.toLocaleString('es-ES', { timeZone: 'Europe/Madrid' });
const fileTimestamp = timestamp.replace(/[:.]/g, '-').replace('T', '_').slice(0, 19);

function esc(str) {
  return String(str || '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/\n/g, '<br>');
}

const mensajesHtml = historia.length
  ? historia.map(msg => {
      const isUser  = msg.role === 'user';
      const label   = isUser ? '👤 Usuario' : '🤖 Asistente';
      const bgColor = isUser ? '#EEF2FF' : '#F0FDF4';
      const border  = isUser ? '#818CF8' : '#4ADE80';
      const labelClr = isUser ? '#3730A3' : '#166534';
      const hora = msg.created_at
        ? new Date(msg.created_at).toLocaleTimeString('es-ES', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' })
        : '';
      return `<div style="margin-bottom:14px;padding:14px 18px;background:${bgColor};border-left:4px solid ${border};border-radius:0 8px 8px 0;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span style="font-size:11px;font-weight:700;color:${labelClr};text-transform:uppercase;letter-spacing:.05em;">${label}</span>${hora ? `<span style="font-size:11px;color:#9CA3AF;">${hora}</span>` : ''}</div><div style="font-size:14px;line-height:1.7;color:#1F2937;">${esc(msg.content)}</div></div>`;
    }).join('')
  : '<p style="color:#6B7280;font-style:italic;">No hay mensajes en el historial.</p>';

const fichaLead = `<div style="margin-top:28px;padding:18px 20px;background:#FFF7ED;border:1px solid #FED7AA;border-radius:8px;"><div style="font-size:11px;font-weight:700;color:#92400E;text-transform:uppercase;letter-spacing:.06em;margin-bottom:14px;">📋 Datos del lead capturado</div><table style="width:100%;border-collapse:collapse;font-size:13px;"><tr><td style="padding:5px 12px 5px 0;color:#6B7280;width:130px;">Nombre</td><td style="padding:5px 0;color:#111827;font-weight:500;">${esc(leadNombre)}</td></tr><tr><td style="padding:5px 12px 5px 0;color:#6B7280;">Email</td><td style="padding:5px 0;color:#111827;">${esc(leadEmail)}</td></tr><tr><td style="padding:5px 12px 5px 0;color:#6B7280;">Teléfono</td><td style="padding:5px 0;color:#111827;">${esc(leadTel)}</td></tr><tr><td style="padding:5px 12px 5px 0;color:#6B7280;">Producto</td><td style="padding:5px 0;color:#111827;">${esc(leadProd)}</td></tr>${leadCtx ? `<tr><td style="padding:5px 12px 5px 0;color:#6B7280;">Contexto</td><td style="padding:5px 0;color:#111827;">${esc(leadCtx)}</td></tr>` : ''}</table></div>`;

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Transcript — Dgtalit Chatbot</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#F9FAFB;color:#111827;padding:32px 16px}.wrap{max-width:780px;margin:0 auto;background:#fff;border-radius:12px;box-shadow:0 1px 4px rgba(0,0,0,.12);overflow:hidden}.hdr{background:linear-gradient(135deg,#1e3a8a,#1a56db);color:#fff;padding:28px 32px}.hdr h1{font-size:20px;font-weight:600;margin-bottom:8px}.hdr p{font-size:13px;opacity:.85;line-height:1.8;margin:0}.body{padding:28px 32px}.sec{font-size:11px;font-weight:700;color:#6B7280;text-transform:uppercase;letter-spacing:.08em;margin-bottom:16px;padding-bottom:8px;border-bottom:1px solid #E5E7EB}.foot{background:#F3F4F6;padding:14px 32px;font-size:11px;color:#9CA3AF;border-top:1px solid #E5E7EB}</style></head><body><div class="wrap"><div class="hdr"><h1>📋 Transcript de conversación</h1><p>🕐 ${fechaLegible}<br>👤 Lead: ${esc(leadNombre)}${leadEmail ? ' &lt;' + esc(leadEmail) + '&gt;' : ''}<br>📨 Total mensajes: ${historia.length}</p></div><div class="body"><div class="sec">Conversación completa</div>${mensajesHtml}${fichaLead}</div><div class="foot">Generado automáticamente por Dgtalit Chatbot · ${timestamp}</div></div></body></html>`;

return [{
  json: {
    html_content:  html,
    file_name:     `transcript_${fileTimestamp}.html`,
    client_id:     clientId,
    company_name:  companyName,
    lead_nombre:   leadNombre,
    lead_email:    leadEmail,
    created_at:    timestamp,
    message_count: historia.length,
    storage_path:  `chatbot/${clientId}/transcript_${fileTimestamp}.html`
  }
}];

const uploadResponse = $json;
const prevData    = $('Generate HTML Transcript').first().json;
const storagePath = prevData.storage_path;
const supabaseUrl = (process.env.SUPABASE_URL || '').replace(/\/$/, '');
const publicUrl   = `${supabaseUrl}/storage/v1/object/public/transcripts/${storagePath}`;
const uploadOk    = uploadResponse.statusCode >= 200 && uploadResponse.statusCode < 300;
const leadData    = $('Preparar Lead Local').first().json.lead || {};

return [{
  json: {
    client_id:      prevData.client_id,
    file_url:       uploadOk ? publicUrl : null,
    storage_path:   storagePath,
    file_name:      prevData.file_name,
    lead_nombre:    prevData.lead_nombre,
    lead_email:     prevData.lead_email,
    message_count:  prevData.message_count,
    created_at:     prevData.created_at,
    upload_status:  uploadOk ? 'OK' : 'ERROR',
    upload_response:JSON.stringify(uploadResponse),
    hasLead: true,
    lead: leadData
  }
}];
